#!/bin/bash
# Creates Generated/TrackPinBuild.swift with a loopback port and a secret token that
# the app and the widget extension share. Runs once per checkout; delete the file to
# get a new port and token.
set -euo pipefail
root="$(cd "$(dirname "$0")/.." && pwd)"
file="$root/Generated/TrackPinBuild.swift"
[[ -s "$file" ]] && exit 0
mkdir -p "$(dirname "$file")"
port="$(( 49152 + RANDOM % 16384 ))"
token="$(/usr/bin/uuidgen)"
cat > "$file" <<GEN
// Generated by scripts/configure.sh. Not committed.
enum TrackPinBuild {
    static let port: UInt16 = $port
    static let token = "$token"
}
GEN
echo "Generated $file (port $port)"
